from heapq import heapify, heapreplace

def findKthLargest(nums, k):
    heap = nums[:k]
    heapify(heap)               # k 大小的小根堆
    for x in nums[k:]:
        if x > heap[0]:
            heapreplace(heap, x)  # 换掉更小的堆顶
    return heap[0]              # 堆顶即第 k 大

from collections import Counter
from heapq import heappush, heapreplace

def topKFrequent(nums, k):
    cnt = Counter(nums)          # 计频
    heap = []
    for x, c in cnt.items():
        if len(heap) < k:
            heappush(heap, (c, x))   # 小根堆存(频次,元素)
        elif c > heap[0][0]:
            heapreplace(heap, (c, x))  # 换掉低频堆顶
    return [x for _, x in heap]

from heapq import heappush, heappop

class MedianFinder:
    def __init__(self):
        self.lo, self.hi = [], []   # 大根堆(存负)/小根堆
    def addNum(self, x):
        heappush(self.lo, -x)
        heappush(self.hi, -heappop(self.lo))  # 小半顶送大半
        if len(self.hi) > len(self.lo):
            heappush(self.lo, -heappop(self.hi))  # 平衡
    def findMedian(self):
        return -self.lo[0] if len(self.lo) > len(self.hi) \
            else (-self.lo[0] + self.hi[0]) / 2
